    H = observation.get("grid_height", 0)
    sx, sy = observation.get("self_position", [0, 0])
    ox, oy = observation.get("opponent_position", [0, 0])
    resources = observation.get("resources", []) or []
    obstacles = observation.get("obstacles", []) or []

    def pos(v):
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if a in v and b in v:
                    return [int(v[a]), int(v[b])]
            for k in ("pos", "position"):
                p = v.get(k)
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    return [int(p[0]), int(p[1])]
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [int(v[0]), int(v[1])]
        return None

    def cells(items):
        out = []
        for it in items if isinstance(items, (list, tuple)) else []:
            p = pos(it)
            if p is not None:
                out.append((p[0], p[1]))
            elif isinstance(it, dict):
                for vv in it.values():
                    p = pos(vv)
                    if p is not None:
                        out.append((p[0], p[1]))
        return out

    res = cells(resources)
    obs = set(cells(obstacles))
    if not res:
        dx = 1 if sx < W - 1 and (sx + 1, sy) not in obs else (-1 if sx > 0 and (sx - 1, sy) not in obs else 0)
        dy = 1 if dx == 0 and sy < H - 1 and (sx, sy + 1) not in obs else (-1 if dx == 0 and sy > 0 and (sx, sy - 1) not in obs else 0)
        return [dx, dy]

    best = None
    bd = 10**9
    for x, y in res:
        d = abs(x - sx) + abs(y - sy)
        if d < bd or (d == bd and (abs(x - ox) + abs(y - oy)) > (abs(best[0] - ox) + abs(best[1] - oy) if best else -1)):
            best = (x, y)
            bd = d

    dx = 0 if best[0] == sx else (1 if best[0] > sx else -1)
    dy = 0 if best[1] == sy else (1 if best[1] > sy else -1)
    cand = [(dx, 0), (0, dy), (dx, dy), (0, 0)]
    for mx, my in cand:
        nx, ny = sx + mx, sy + my
        if 0 <= nx < W and 0 <= ny < H and (nx, ny) not in obs:
            return [mx, my]
    return [0, 0]

